custom_css:
/* ============================================================
   少女祷告 @Mayonnaise
   非常感谢导航楼内各位老师的分享，所使用代码已在以下标注作者❤︎
   ============================================================ */
@import url("https://fontsapi.zeoseven.com/924/main/result.css");

body {
    font-family: "GenKiMin2 TC";
    font-weight: normal;
}

::selection {
    background: var(--SmartThemeQuoteColor);
}

/* 头像框 */
.mesAvatarWrapper::after {
    content: "";
    position: absolute;
    top: -1px;
    left: -11px;
    width: 102px;
    height: 102px;
    background-image: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E5%B0%91%E5%A5%B3%E7%A5%B7%E5%91%8A/txk3.png') !important;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    z-index: 1 !important;
  pointer-events: none;
}

/* ============================================================
   2. 页面整体布局 (Layout)
   ============================================================ */
#right-nav-panel, #left-nav-panel {
    background-image: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E5%B0%91%E5%A5%B3%E7%A5%B7%E5%91%8A/%E6%8F%92%E7%94%BB1.png');
    background-size: contain;
    background-repeat: repeat;
    border-radius: 5px;
    max-height: 100vh !important;
}

#top-bar {
    background-image: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E5%B0%91%E5%A5%B3%E7%A5%B7%E5%91%8A/%E6%8F%92%E7%94%BB1.png');
    box-shadow: none;
    border: none;
}

#top-bar::before {
    content: '';
    position: absolute;
    background-image: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E5%B0%91%E5%A5%B3%E7%A5%B7%E5%91%8A/806f853b-488f-40a3-9d3b-9cabcbd0dde7%20%E6%8B%B7%E8%B4%9D.png');
    background-size: contain;
    background-repeat: repeat;
    background-position: center;
    width: 100%;
    height: 38px;
    top: 12px;
}

/* ============================================================
   3. 侧边栏与设置区块 (Sidebar & Settings Panels)
   ============================================================ */
#rm_api_block,#AdvancedFormatting,#WorldInfo,#user-settings-block,#Backgrounds,#bg-header-fixed,#bg_tabs,#rm_extensions_block,#PersonaManagement{
      background-image: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E5%B0%91%E5%A5%B3%E7%A5%B7%E5%91%8A/%E6%8F%92%E7%94%BB4.png');
    background-size: 40%;
    background-repeat: repeat;
    border-radius: 5px;
}

#rm_extensions_block .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader{
    background: #ffffff90;
    border-radius: 5px;
    padding: 4px;
    box-shadow: 0 1px 2px 0 #E1D7DB80;
    transition: 0.4s ease;
}

#rm_extensions_block .inline-drawer-toggle.inline-drawer-header{
    padding: 7px;
    margin-bottom: 7px;
}

#rm_extensions_block .inline-drawer-toggle.inline-drawer-header:hover {
    padding-left: 10px;
    filter: drop-shadow(0 0 5px var(--SmartThemeQuoteColor));
}

:is(#rm_extensions_block .inline-drawer-header, #user-settings-block h4, .standoutHeader,.mes .name_text)::before {
    content: "♡♱ ";
}

.world_entry_form.wi-card-entry{
    background: #ffffff90;
    padding: 3px;
    margin-bottom: 5px;
}

.regex-script-label.flex-container.flexnowrap{
    background: #ffffff80;
}

.reverse_proxy_warning{
    background: #ffffff90!important;
    color: var(--SmartThemeQuoteColor)!important;
}

/* ============================================================
   4. 聊天主区域与滚动条 (Chat Main Area)
   ============================================================ */
#chat{
    backdrop-filter: none;
    background: transparent;
    border: none;
    padding: 10px;
    mask: linear-gradient(to bottom, black 0%, black 90%, transparent 100%);
}

/* 滚动条by墨千尾老师 */
::-webkit-scrollbar {
    width: 5px;  
}

::-webkit-scrollbar-thumb {
    border: none !important;
    box-shadow: 0 0 5px #E1D7DB !important;
    background: white !important;  
}

#chat::-webkit-scrollbar-thumb {
    box-shadow: inset -1px 0 3px #E1D7DB90 !important;
}

@media (max-width: 600px) {
    #chat::-webkit-scrollbar {
        display: none;
    }
}

/* ============================================================
   5. 消息气泡整体样式 (Message Bubbles)
   ============================================================ */
.mes{
    background-image: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E5%B0%91%E5%A5%B3%E7%A5%B7%E5%91%8A/%E6%8F%92%E7%94%BB1.png');
    background-size: 45%;
    background-repeat: repeat;
    border-radius: 5px!important;
    margin-bottom: 30px;
    margin-top: 120px;
    padding-bottom: 50px!important;
    border: 1px solid #E1D7DB70;
}

.mes.selected{
    background: #E1D8DC90 !important;
}

.mes_text{
    background-image: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E5%B0%91%E5%A5%B3%E7%A5%B7%E5%91%8A/%E6%8F%92%E7%94%BB4.png');
    background-size: 50%;
    margin: 10px;
    background-blend-mode: screen!important;
    background-color: #aaa;
    padding: 12px;
    border: 1px solid #E1D8DC70;
}

[is_user="false"] .mes_text{
    padding-bottom: 30px;
}

.mes_block{
    padding: 0;
    overflow: hidden !important;
}

/* 去除最后一条消息和内容之间的间距byblue老师 */
.mes.last_mes > *:not(.mes_block) {
    padding-bottom: 0;
}

.last_mes{
    margin-bottom: 50px!important;
}

.mes:not(:has(.mes_reasoning:not(:empty))) .mes_text {
    margin-top: 60px !important;
}

/* ============================================================
   6. 消息装饰与元数据 (Avatars, Names & Metadata)
   ============================================================ */
.mesAvatarWrapper{
    position: absolute;
    top: -100px;
    left: 50%;
    transform: translateX(-50%);
}

.mes .avatar img{
    width: 80px;
    height: 80px;
    box-shadow: inset 0 10px 2px #fff!important;
    border: none!important;
}

.mes .avatar{
    width: 80px;
    height: 80px;
}

.mes .name_text{
    position: absolute;
    left: 50%;
    transform: translateX(-50%);
    top: 12px;
    font-size: 15px;
    text-shadow: 0 1px 5px var(--SmartThemeQuoteColor);
}

.mes .name_text::after{
    content: " ♱♡";
}

.mes .mes_timer, .mes .mesIDDisplay, .mes .tokenCounterDisplay{
    position: absolute;
    top: 85px;
    opacity: 0;
    transition: opacity 1.5s ease;
    font-size: 10px;
    text-shadow: 0 0 4px #fff;
    z-index: 2;
}

.mesIDDisplay{ left: -10px; }
.mes_timer{ left: 30px; }
.tokenCounterDisplay{ left: 80px; }

.mes:hover .mes_timer, .mes:hover .mesIDDisplay, .mes:hover .tokenCounterDisplay{
    opacity: 0.8;
}

.timestamp{
    position: absolute;
    bottom: 10px;
    left: 50%;
    transform: translateX(-50%);
    opacity: 0;
    transition: opacity 1.5s ease;
    text-shadow: 0 0 3px #E1D7DB;
}

.timestamp::before{
    content: '✧ Timestamp ✧';
    display: block;
    text-align: center;
    font-style: italic;
    line-height: 1rem;
}

.mes:hover .swipes-counter,.mes:hover .timestamp {
    opacity: 0.45;
}

.mes_ghost.fa-solid.fa-ghost{
    color: #E1D7DB;
    font-size: 17px;
}

/* ============================================================
   7. 消息背景装饰 (Message Background Decorations)
   ============================================================ */
.mes_block::before{
    content: '';
    position: absolute;
    background-image: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E5%B0%91%E5%A5%B3%E7%A5%B7%E5%91%8A/806f853b-488f-40a3-9d3b-9cabcbd0dde7(UpRGB)(scale)(x2.000000).png');
    background-size: auto 60px !important;
    background-repeat: repeat-x!important;
    width: 100%;
    height: 100%;
    top: 30px;
    left: 50%;
    transform: translateX(-50%);
    pointer-events: none;
}

@media (max-width: 600px) {
    .mes_block::before {
        background-size: contain ;
        height: 55px;
        top: 35px;
    }
}

.mes_block::after {
    content: '' !important; 
    position: absolute;
    bottom: 0px;  
    left: -130px;    
    right: -130px;   
    height: 300px;   
    background-image: 
        url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E5%B0%91%E5%A5%B3%E7%A5%B7%E5%91%8A/zuo.png'), 
        url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E5%B0%91%E5%A5%B3%E7%A5%B7%E5%91%8A/you.png') !important;
    background-position: 
        left bottom, 
        right bottom !important;
    background-repeat: 
        no-repeat, 
        no-repeat !important;
    background-size: 
        contain, 
        contain !important;
    pointer-events: none;
    transition: all 2s ease;
}

@media (max-width: 600px) {
    .mes_block::after {
        height: 250px !important;
        left: -110px !important;
        right: -110px !important;
    }

    .mes_block:hover::after,
    .mes_block:active::after {
        left: -170px !important;  
        right: -170px !important;
        filter: drop-shadow(0 0 3px #E1D7DB); 
    }
}

@media (min-width: 601px) {
    .mes_block:hover::after {
        left: -220px !important;
        right: -220px !important;
      filter: drop-shadow(0 0 3px #E1D7DB);
    }
}

/* ============================================================
   8. 消息内文本格式化 (In-message Content Styles)
   ============================================================ */
.mes_text q{
    background: #ffffff85;
    padding: 3px;
    box-shadow: 0 2px 3px 0px color-mix(in srgb, var(--SmartThemeQuoteColor), transparent 60%);
    line-height: 1.6rem;
}

.mes_text code{
    display: inline;
    -webkit-box-decoration-break: clone;
    box-decoration-break: clone;
    color: var(--SmartThemeQuoteColor);
    font-family: "GenKiMin2 TC";
    padding: 4px;
    background: white;
    border: 1px solid #E1D7DB80;
    box-shadow: 0 2px 4px 0px color-mix(in srgb, var(--SmartThemeQuoteColor), transparent 60%);
    line-height: 1.6rem;
}

.mes_text blockquote{
    background: white;
    color: var(--SmartThemeUnderlineColor);
}

.mes_text pre{
    background: white;
    font-family: "GenKiMin2 TC";
    border: 1px dotted #E1D7DB;
    padding: 2px;
}

/* ============================================================
   9. 思考区样式 (Reasoning / Thinking Process)
   ============================================================ */
.mes_reasoning{
    color: #C0BCBE;
    background: #ffffff95;
    border: 1px dashed var(--SmartThemeQuoteColor);
    margin-top: 5px;
}

.mes_reasoning_details {
    position: relative !important;
    width: 95%;
    margin: auto;
}

.mes_reasoning_edit_done,
.mes_reasoning_edit_cancel,
.mes_reasoning_actions .edit_button,
.mes_reasoning_actions .menu_button {
    color: #8A7D85;
    border: 1px solid #E1D7DB;
    border-radius: 5px;
    font-size: 13px;
    transition: all 0.3s ease-in-out;
    transform: scale(0.9);
    filter: none;
}

.mes_reasoning_actions .menu_button:hover {
    box-shadow: 0 0 5px #E1D8DC;
}

.reasoning_edit_textarea{
    margin-top: 20px;
}

.mes_reasoning_header.flex-container {
    padding: none!important;
    margin: none!important;
    left: 48%;
    transform: translateX(-50%);
    background: transparent;
}

.mes_reasoning_header {
    display: flex !important;
    font-size: 0;
}

.mes_reasoning_header::before {
    content: '';
    background-image: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E5%B0%91%E5%A5%B3%E7%A5%B7%E5%91%8A/806f853b-488f-40a3-9d3b-9cabcbd0dde7%20%E6%8B%B71%E8%B4%9D.png');
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    width: 55px;
    height: 55px;
    filter: drop-shadow(0 0 1px #E1D7DB) !important;
    transition: filter 0.7s ease!important;
}

.mes_reasoning_header:hover::before{
    filter: drop-shadow(0 0 4px #E1D7DB) !important;
}

.mes_reasoning_arrow { display: none; }

.mes_reasoning_actions.flex-container { 
    position: absolute;
    top: 45px;
}

/* ============================================================
   10. 交互按钮与翻页图标 (Interaction & Navigation Icons)
   ============================================================ */
.mes_buttons{
    position: absolute;
    bottom: 50px;
    left: 50%;
    transform: translateX(-50%);
    opacity: 0;
    transition: all 1.5s ease;
}

.mes:hover .mes_buttons{
    opacity: 1;
}

.mes_edit_buttons{
    position: absolute;
    bottom: 50px;
    left: 50%;
    transform: translateX(-50%) scale(0.8);
    bottom: 55px;
}

.mes_edit, .extraMesButtonsHint {
    font-size: 0;
    filter: none;
    width: 20px;   
    height: 20px;
    background-size: contain;
    background-repeat: no-repeat;
    opacity: 1;
    transition: all 0.5s ease;
    background-image: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E5%B0%91%E5%A5%B3%E7%A5%B7%E5%91%8A/97a26141-37ec-4278-9bb3-4fa13f0d4940.png') !important; 
    margin-left: 15px;
    margin-right: 5px;
}

.mes_edit:hover, .extraMesButtonsHint:hover {
    filter: drop-shadow(0 0 5px #E1D7DB)!important; 
}

.mes_button, .extraMesButtons .mes_button,.mes_edit_buttons{
    filter: none!important;
}

/* 翻页图标替换二改by 眠N勿扰老师 */
.swipe_left::before, .swipe_right::before { content: '' !important; }

.swipe_left, .swipe_right {
    position: absolute !important;
    bottom: 9px !important;
    opacity: 1 !important;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    transition: all 0.5s ease !important;
    width: 40px;
    height: 40px;
}

.swipe_left {
    background-image: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E5%B0%91%E5%A5%B3%E7%A5%B7%E5%91%8A/1.png');
}

.swipe_right {
    background-image: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E5%B0%91%E5%A5%B3%E7%A5%B7%E5%91%8A/2.png');
}

.swipe_left:hover, .swipe_right:hover { filter: drop-shadow(0 0 3px #E1D7DB); }

[is_user="false"] .swipes-counter{
    margin: 65px 25px !important;
    text-shadow: 0 0 3px #E1D7DB;
    font-style: italic;
    font-family: "GenKiMin2 TC";
    font-size: 10px;
    white-space: nowrap;
    left: 0 !important;
    right: 0 !important;
    width: 100% !important;
    text-align: center !important;
    opacity: 0;
    transition: opacity 1.5s ease;
}

[is_user="false"] .swipes-counter::before{
    content: '✦ ݁Praying... ';
}

[is_user="false"] .swipes-counter::after{
    content: ' ✦';
}

/* ============================================================
   11. 底部发送栏美化 (Send Form & Textarea)
   ============================================================ */
#send_textarea{
    font-family: "GenKiMin2 TC";
    background-image: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E5%B0%91%E5%A5%B3%E7%A5%B7%E5%91%8A/%E6%8F%92%E7%94%BB4.png');
    background-blend-mode: screen!important;
    background-color: #aaa!important;
}

#send_form{
    position: absolute;
    background-image: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E5%B0%91%E5%A5%B3%E7%A5%B7%E5%91%8A/%E6%8F%92%E7%94%BB1.png');
    background-size: contain;
    background-position: center;
    padding: 0 5px 10px 5px;
    bottom: 5px;
    width: 90%;
    left: 50%;
    transform: translateX(-50%);
    border-radius: 10px;
    transition: all 1.5s ease;
    border: 1px solid #E1D7DB70 !important;
}

#send_form::before{
    content: '';
    background-image: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E5%B0%91%E5%A5%B3%E7%A5%B7%E5%91%8A/806f853b-488f-40a3-9d3b-9cabcbd0dde7(UpRGB)(scale)(x2.000000).png');
    background-position: center;
    height: 11px;
    width: 100%;
    position: absolute;
    bottom: 4px;
    z-index: 1;
    background-repeat: repeat-x;
    background-size: contain;
    left: 50%;
    transform: translateX(-50%);
    filter: drop-shadow(0 0 2px #E1D7DB);
}

#send_form::after{
    content: '';
    background-image: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E5%B0%91%E5%A5%B3%E7%A5%B7%E5%91%8A/806f853b-488f-40a3-9d3b-9cabcbd0dde7%20%E6%8B%B71%E8%B4%9D.png');
    background-size: contain;
    background-repeat: no-repeat;
    width: 45px;
    height: 45px;
    position: absolute;
    filter: drop-shadow(0 0 1px #84818280);
    left: 50%;
    transform: translateX(-50%);
    top: -15px;
}

#send_form:hover{
    filter: drop-shadow(0 0 2px #E1D7DB);
    transform: translateX(-50%) translateY(-5px);
}

/* 输入框文字by hgu老师 */
#send_textarea::placeholder {
    color: transparent !important;
    opacity: 0 !important;
}

#nonQRFormItems {
    position: relative !important;
}

#nonQRFormItems:has(#send_textarea:placeholder-shown)::after {
    content: '˚₊‧꒰ა ♡ ໒꒱ ‧₊˚';
    font-size: 14px;
    white-space: nowrap;
    opacity: 0.5;
    position: absolute;
    z-index: 10;
    pointer-events: none;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
}

/* 隐藏QR栏二改by 12老师 */
#qr--bar {
    max-height: 0 !important;
    opacity: 0 !important;
    pointer-events: none;
    transition: all 2s !important;
    cubic-bezier(0.175, 0.885, 0.32, 1.275)
}

#send_form:focus-within #qr--bar {
    max-height: 120px !important;
    opacity: 1 !important;
    pointer-events: auto;
}

/* ============================================================
   12. 功能按钮与图标全局美化 (General UI Buttons & Icons)
   ============================================================ */
.menu_button {
    background: #fff!important;
    color: var(--SmartThemeQuoteColor);
    transition: all 0.4s ease;
}

.menu_button:hover{
    box-shadow: 0 2px 4px 0px var(--SmartThemeQuoteColor);
    color: #fff;
    background: var(--SmartThemeQuoteColor)!important;
}

.avatar-container.interactable{
    background: #ffffff85;
    border-radius: 7px;
    box-shadow: 0 2px 4px 0px #E1D7DB90;
    padding: 9px!important;
    margin-top: 5px;
    transition: padding 0.5s ease,filter 0.4s ease;
    font-size: var(--mainFontFamily);
}

.avatar-container.interactable:hover{
    padding: 15px!important;
    filter: drop-shadow(0 0 5px var(--SmartThemeQuoteColor));
}

.avatar-container.interactable.selected {
    border: 1px solid var(--SmartThemeBorderColor);
}

.fa-circle-chevron-down,
.fa-circle-chevron-up,
.inline-drawer-icon.fa-circle-chevron-down,
.inline-drawer-icon.fa-circle-chevron-up {
    filter: none;
    background-image: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E5%B0%91%E5%A5%B3%E7%A5%B7%E5%91%8A/98a4f8d6-63d9-443c-8a86-4673feccc08e.png') !important;
    background-size: contain !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    width: 15px !important;
    height: 15px !important;
    display: inline-block !important; 
    transition: all 0.3s ease-in-out !important;
}

.fa-circle-chevron-down::before,
.fa-circle-chevron-up::before {
    content: "" !important;
}

.fa-circle-chevron-up,
.inline-drawer-icon.fa-circle-chevron-up {
    filter: drop-shadow(0 0 4px #E1D7DB);
}

/* 顶栏图标替换by 秦素老师 */
#top-settings-holder > div > :first-child > * {
    opacity: 0 !important;
  }

#top-settings-holder > div > :first-child {
    display: block;
    background-size: contain;
    background-position: center;
    background-repeat: no-repeat;
    transition: all 0.5s ease-in-out;
    width: 33px;
    height: 33px;
    opacity: 1 !important;
}

#top-settings-holder .drawer-toggle:hover,
  #top-settings-holder .drawer:has(.drawer-content.openDrawer) .drawer-toggle {
    filter: drop-shadow(0 0 5px #E1D7DB);
}

#top-settings-holder > .drawer:nth-of-type(odd) .drawer-toggle {
