/* ============================================================
   13. 输入框、选择框与交互细节 (Form Elements)
   ============================================================ */
:is(
    .text_pole, 
    select, 
    input:not([type="checkbox"]), 
    [id*="textarea"], 
    [class*="textarea"], 
    [class*="select2-selection"]
) {
    background-image: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E5%B0%91%E5%A5%B3%E7%A5%B7%E5%91%8A/%E6%8F%92%E7%94%BB4.png');
    background-size: 50%;
    background-blend-mode: screen;
    background-color: #ffffff50!important;
    font-family: "GenKiMin2 TC";
    border-radius: 4px;
}

select option {
    font-family: "GenKiMin2 TC";
    color: var(--SmartThemeBodyColor) !important;
    background-color: #fff !important;
}

.select2-selection__choice__display,
.select2-selection__choice__remove {
    background: none !important;
}

/* 滑动条by 墨千尾老师 */
input[type="range"] { 
    filter: none !important; 
}

input[type="range"]::-webkit-slider-runnable-track {
    width: 100%;
    height: 5px;
    background: white; 
    border-radius: 3px;
    border: none;
    filter: drop-shadow(0 0 2px #E1D7DB);
}

input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    top: -4px;
    height: 15px;
    width: 15px;
    background-image: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E5%B0%91%E5%A5%B3%E7%A5%B7%E5%91%8A/98a4f8d6-63d9-443c-8a86-4673feccc08e.png');
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    background-color: transparent;
    border: none;
    border-radius: 0;
    box-shadow: none;
    transition: all 0.5s ease-in-out;
}

input[type="range"]:hover::-webkit-slider-thumb { filter: drop-shadow(0 0 5px #E1D7DB); }

/* 复选框二改by食南瓜者老师 */
input[type="checkbox"] {
    appearance: none;
    -webkit-appearance: none;
    width: 15px;
    height: 15px;
    background-color: #fff;
    transition: all 0.4s ease;
    cursor: pointer;
    position: relative;
    -webkit-mask-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/></svg>');
    mask-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/></svg>');
    -webkit-mask-repeat: no-repeat;
    mask-repeat: no-repeat;
    -webkit-mask-size: contain;
    mask-size: contain;
}

input[type="checkbox"]:checked {
    background-color: #B1ADAF;
}

input[type="checkbox"]:hover {
    background-color: #B1ADAF40;
}

input[type="checkbox"]::after, input[type="checkbox"]::before {
    display: none !important;
}

